// Record the confirmed trend requirement without assigning a trade grade.
return $input.all().map((item, index) => {
  const { direction, trendDirection } = item.json;
  const validDirections = ["BUY", "SELL"];
  const trendStatus = validDirections.includes(direction) && validDirections.includes(trendDirection)
    ? (direction === trendDirection ? "ALIGNED" : "OPPOSED")
    : "UNDETERMINED";

  return {
    json: {
      ...item.json,
      gradingReview: {
        allowedGradeLabels: ["A+", "A", "B+"],
        aPlusTrendRequirement: trendStatus,
        tradeGrade: null,
        allInZone: null,
        status: "WAIT",
        notificationAllowed: false,
      },
    },
    pairedItem: { item: index },
  };
});
